def seed_content(apps, schema_editor):
    """مقدار اولیهٔ تنظیمات/محتوا؛ بعد از آن مدیر از پنل مدیریت می‌کند"""
    from shop import defaults as d
    SiteSetting = apps.get_model('shop', 'SiteSetting')
    for key, val in (('info', d.INFO), ('shipping', d.SHIPPING_SETTINGS), ('lucky', d.LUCKY_SETTINGS)):
        SiteSetting.objects.get_or_create(key=key, defaults={'value': val})
    ShippingMethod = apps.get_model('shop', 'ShippingMethod')
    for i, (key, label, cost, days, hint) in enumerate(d.SHIPPING_METHODS):
        ShippingMethod.objects.get_or_create(key=key, defaults=dict(label=label, cost=cost, days=days, hint=hint, sort=i))
    Page = apps.get_model('shop', 'Page')
    for i, (slug, title, kind, group, body, items) in enumerate(d.PAGES):
        Page.objects.get_or_create(slug=slug, defaults=dict(title=title, kind=kind, group=group, body=body, items=items, sort=i))
    LuckyPrize = apps.get_model('shop', 'LuckyPrize')
    if not LuckyPrize.objects.exists():
        for title, desc, kind, value, mn, w, ic in d.LUCKY_PRIZES:
            LuckyPrize.objects.create(title=title, desc=desc, kind=kind, value=value, min_total=mn, weight=w, icon=ic)
    # کدهای قدیمیِ کارت شانس همگانی بودند (هر کس می‌توانست بی‌نهایت استفاده کند) → از این پس جایزه‌ها کد شخصی یک‌بارمصرف‌اند
    Coupon = apps.get_model('shop', 'Coupon')
    Coupon.objects.filter(code__in=['LUCK5', 'LUCK20', 'NEXT15', 'SHIP0', 'CASH50', 'SAMEDAY']).update(active=False)


